    if (webSearch != null) 'webSearchSecrets',
    if (mcp != null) 'mcpTransportFactory',
    if (sqlite != null) 'sqliteEngine',
    if (lsp != null) 'lspTransportFactory',
    if (vision != null) 'visionConfig',
